1	package notification
2	
3	import (
4		"context"
5		"fmt"
6		"log/slog"
7		"strings"
8	
9		"github.com/pkg/errors"
10	
11		"github.com/usememos/memos/internal/email"
12		"github.com/usememos/memos/internal/profile"
13		storepb "github.com/usememos/memos/proto/gen/store"
14		"github.com/usememos/memos/store"
15	)
16	
17	// EmailSender sends a prepared email message with the given SMTP configuration.
18	type EmailSender func(*email.Config, *email.Message)
19	
20	// EmailDispatcher dispatches notification emails for inbox events.
21	type EmailDispatcher struct {
22		profile *profile.Profile
23		store   *store.Store
24		sender  EmailSender
25	}
26	
27	// NewEmailDispatcher creates a notification email dispatcher.
28	func NewEmailDispatcher(profile *profile.Profile, store *store.Store, sender EmailSender) *EmailDispatcher {
29		if sender == nil {
30			sender = email.SendAsync
31		}
32		return &EmailDispatcher{
33			profile: profile,
34			store:   store,
35			sender:  sender,
36		}
37	}
38	
39	// DispatchInboxEmail sends the email notification for an inbox entry when configured.
40	func (d *EmailDispatcher) DispatchInboxEmail(ctx context.Context, inbox *store.Inbox) error {
41		if inbox == nil || inbox.Message == nil {
42			return nil
43		}
44	
45		setting, err := d.store.GetInstanceNotificationSetting(ctx)
46		if err != nil {
47			return errors.Wrap(err, "failed to get notification setting")
48		}
49		emailSetting := setting.GetEmail()
50		if emailSetting == nil || !emailSetting.Enabled {
51			return nil
52		}
53		if d.baseURL() == "" {
54			slog.Warn("Skipping inbox email notification because instance URL is required",
55				slog.Int64("inbox_id", int64(inbox.ID)),
56				slog.Int64("receiver_id", int64(inbox.ReceiverID)))
57			return nil
58		}
59	
60		receiver, err := d.store.GetUser(ctx, &store.FindUser{ID: &inbox.ReceiverID})
61		if err != nil {
62			return errors.Wrap(err, "failed to get notification receiver")
63		}
64		if receiver == nil || strings.TrimSpace(receiver.Email) == "" {
65			return nil
66		}
67	
68		sender, err := d.store.GetUser(ctx, &store.FindUser{ID: &inbox.SenderID})
69		if err != nil {
70			return errors.Wrap(err, "failed to get notification sender")
71		}
72		if sender == nil {
73			return nil
74		}
75	
76		memosByID, err := d.listMemosByID(ctx, collectInboxMemoIDs([]*store.Inbox{inbox}))
77		if err != nil {
78			return errors.Wrap(err, "failed to get notification memos")
79		}
80	
81		message, err := d.buildInboxEmailMessage(inbox, receiver, sender, memosByID)
82		if err != nil {
83			return err
84		}
85		if message == nil {
86			return nil
87		}
88		message.ReplyTo = emailSetting.ReplyTo
89	
90		config := EmailConfigFromInstanceSetting(emailSetting)
91		if err := config.Validate(); err != nil {
92			return errors.Wrap(err, "invalid notification email setting")
93		}
94	
95		d.sender(config, message)
96		return nil
97	}
98	
99	// EmailConfigFromInstanceSetting converts persisted notification settings into SMTP config.
100	func EmailConfigFromInstanceSetting(setting *storepb.InstanceNotificationSetting_EmailSetting) *email.Config {
101		if setting == nil {
102			return &email.Config{}
103		}
104		return &email.Config{
105			SMTPHost:     setting.SmtpHost,
106			SMTPPort:     int(setting.SmtpPort),
107			SMTPUsername: setting.SmtpUsername,
108			SMTPPassword: setting.SmtpPassword,
109			FromEmail:    setting.FromEmail,
110			FromName:     setting.FromName,
111			UseTLS:       setting.UseTls,
112			UseSSL:       setting.UseSsl,
113		}
114	}
115	
116	// NewTestEmailMessage builds the plain-text test email for notification settings.
117	func NewTestEmailMessage(recipientEmail, replyTo string) *email.Message {
118		return &email.Message{
119			To:      []string{recipientEmail},
120			Subject: "[Memos] Test email",
121			Body:    "This is a test email from your Memos notification settings.",
122			ReplyTo: replyTo,
123		}
124	}
125	
126	// ValidateEmailSetting validates notification email SMTP settings.
127	func ValidateEmailSetting(setting *storepb.InstanceNotificationSetting_EmailSetting) error {
128		return EmailConfigFromInstanceSetting(setting).Validate()
129	}
130	
131	// SendTestEmail sends a plain-text test email using notification email settings.
132	func SendTestEmail(setting *storepb.InstanceNotificationSetting_EmailSetting, recipientEmail string) error {
133		return email.Send(EmailConfigFromInstanceSetting(setting), NewTestEmailMessage(recipientEmail, setting.GetReplyTo()))
134	}
135	
136	func (d *EmailDispatcher) buildInboxEmailMessage(inbox *store.Inbox, receiver *store.User, sender *store.User, memosByID map[int32]*store.Memo) (*email.Message, error) {
137		senderName := displayNameForEmail(sender)
138		switch inbox.Message.Type {
139		case storepb.InboxMessage_MEMO_COMMENT:
140			return d.buildMemoCommentEmailMessage(inbox.Message, receiver, senderName, memosByID)
141		case storepb.InboxMessage_MEMO_MENTION:
142			return d.buildMemoMentionEmailMessage(inbox.Message, receiver, senderName, memosByID)
143		default:
144			return nil, nil
145		}
146	}
147	
148	func (d *EmailDispatcher) buildMemoCommentEmailMessage(message *storepb.InboxMessage, receiver *store.User, senderName string, memosByID map[int32]*store.Memo) (*email.Message, error) {
149		payload := message.GetMemoComment()
150		if payload == nil {
151			return nil, nil
152		}
153		commentMemo := memosByID[payload.MemoId]
154		relatedMemo := memosByID[payload.RelatedMemoId]
155		if !canViewerAccessMemo(receiver, commentMemo) || !canViewerAccessMemo(receiver, relatedMemo) {
156			return nil, nil
157		}
158		url := d.memoCommentURL(relatedMemo, commentMemo)
159		if url == "" {
160			return nil, nil
161		}
162	
163		body := []string{
164			fmt.Sprintf("Hi %s,", displayNameForEmail(receiver)),
165			"",
166			fmt.Sprintf("%s commented on your memo.", senderName),
167			"",
168			"Open in Memos:",
169			url,
170			"",
171			"You are receiving this because you own this memo.",
172		}
173	
174		return &email.Message{
175			To:      []string{receiver.Email},
176			Subject: fmt.Sprintf("[Memos] %s commented on your memo", senderName),
177			Body:    strings.Join(body, "\n"),
178		}, nil
179	}
180	
181	func (d *EmailDispatcher) buildMemoMentionEmailMessage(message *storepb.InboxMessage, receiver *store.User, senderName string, memosByID map[int32]*store.Memo) (*email.Message, error) {
182		payload := message.GetMemoMention()
183		if payload == nil {
184			return nil, nil
185		}
186		memo := memosByID[payload.MemoId]
187		if !canViewerAccessMemo(receiver, memo) {
188			return nil, nil
189		}
190		url := d.memoURL(memo)
191		if url == "" {
192			return nil, nil
193		}
194	
195		body := []string{
196			fmt.Sprintf("Hi %s,", displayNameForEmail(receiver)),
197			"",
198			fmt.Sprintf("%s mentioned you in a memo.", senderName),
199			"",
200			"Open in Memos:",
201			url,
202			"",
203			"You are receiving this because you were mentioned in this memo.",
204		}
205	
206		return &email.Message{
207			To:      []string{receiver.Email},
208			Subject: fmt.Sprintf("[Memos] %s mentioned you in a memo", senderName),
209			Body:    strings.Join(body, "\n"),
210		}, nil
211	}
212	
213	func (d *EmailDispatcher) listMemosByID(ctx context.Context, memoIDs []int32) (map[int32]*store.Memo, error) {
214		if len(memoIDs) == 0 {
215			return map[int32]*store.Memo{}, nil
216		}
217	
218		uniqueMemoIDs := make([]int32, 0, len(memoIDs))
219		seenMemoIDs := make(map[int32]struct{}, len(memoIDs))
220		for _, memoID := range memoIDs {
221			if memoID == 0 {
222				continue
223			}
224			if _, seen := seenMemoIDs[memoID]; seen {
225				continue
226			}
227			seenMemoIDs[memoID] = struct{}{}
228			uniqueMemoIDs = append(uniqueMemoIDs, memoID)
229		}
230		if len(uniqueMemoIDs) == 0 {
231			return map[int32]*store.Memo{}, nil
232		}
233	
234		memos, err := d.store.ListMemos(ctx, &store.FindMemo{IDList: uniqueMemoIDs})
235		if err != nil {
236			return nil, err
237		}
238	
239		memosByID := make(map[int32]*store.Memo, len(memos))
240		for _, memo := range memos {
241			memosByID[memo.ID] = memo
242		}
243		return memosByID, nil
244	}
245	
246	func collectInboxMemoIDs(inboxes []*store.Inbox) []int32 {
247		memoIDs := make([]int32, 0, len(inboxes)*2)
248		for _, inbox := range inboxes {
249			if inbox == nil || inbox.Message == nil {
250				continue
251			}
252			switch inbox.Message.Type {
253			case storepb.InboxMessage_MEMO_COMMENT:
254				payload := inbox.Message.GetMemoComment()
255				if payload != nil {
256					memoIDs = append(memoIDs, payload.MemoId, payload.RelatedMemoId)
257				}
258			case storepb.InboxMessage_MEMO_MENTION:
259				payload := inbox.Message.GetMemoMention()
260				if payload != nil {
261					memoIDs = append(memoIDs, payload.MemoId, payload.RelatedMemoId)
262				}
263			default:
264				// Ignore notification types without memo references.
265			}
266		}
267		return memoIDs
268	}
269	
270	func displayNameForEmail(user *store.User) string {
271		if user == nil {
272			return "there"
273		}
274		if strings.TrimSpace(user.Nickname) != "" {
275			return user.Nickname
276		}
277		if strings.TrimSpace(user.Username) != "" {
278			return user.Username
279		}
280		return "there"
281	}
282	
283	func (d *EmailDispatcher) baseURL() string {
284		if d.profile == nil || strings.TrimSpace(d.profile.InstanceURL) == "" {
285			return ""
286		}
287		return strings.TrimRight(strings.TrimSpace(d.profile.InstanceURL), "/")
288	}
289	
290	func (d *EmailDispatcher) memoURL(memo *store.Memo) string {
291		baseURL := d.baseURL()
292		if memo == nil || memo.UID == "" || baseURL == "" {
293			return ""
294		}
295		return fmt.Sprintf("%s/memos/%s", baseURL, memo.UID)
296	}
297	
298	func (d *EmailDispatcher) memoCommentURL(relatedMemo *store.Memo, commentMemo *store.Memo) string {
299		baseURL := d.baseURL()
300		if relatedMemo == nil || relatedMemo.UID == "" || commentMemo == nil || commentMemo.UID == "" || baseURL == "" {
301			return ""
302		}
303		return fmt.Sprintf("%s/memos/%s#%s", baseURL, relatedMemo.UID, commentMemo.UID)
304	}
305	
306	func canViewerAccessMemo(viewer *store.User, memo *store.Memo) bool {
307		if memo == nil {
308			return false
309		}
310		if viewer != nil && viewer.Role == store.RoleAdmin {
311			return true
312		}
313		if memo.Visibility == store.Private {
314			return viewer != nil && viewer.ID == memo.CreatorID
315		}
316		if memo.Visibility == store.Protected {
317			return viewer != nil
318		}
319		return true
320	}
